const freshDefaults={version:5,assessmentEngineVersion:0,assessmentComplete:false,assessmentReport:null,player:{name:'Jugador',age:null,height:null,weight:null,context:'trabajo',goal:'general',createdAt:null},avatar:'',baseSkills:Object.fromEntries(allSkills.map(k=>[k,50])),skillConfidence:Object.fromEntries(allSkills.map(k=>[k,'baja'])),nutritionKnowledge:0,assessmentCompletedAt:null,useMeasuredStrength:false,strength:[{name:'Ejercicio de fuerza 1',current:0,max:100},{name:'Ejercicio de fuerza 2',current:0,max:100},{name:'Ejercicio de fuerza 3',current:0,max:100},{name:'Ejercicio de fuerza 4',current:0,max:100},{name:'Ejercicio de fuerza 5',current:0,max:100},{name:'Ejercicio de fuerza 6',current:0,max:100}],reminderTime:'21:00',reminderText:'Completá tu registro de Vida RPG',days:{},bestStreak:0,academyProgress:{},monetization:{premium:false,bonusLessons:{}},dietProfile:{goal:'lose',sex:'male',activity:'1.5',meals:4,style:'omnivore',budget:'normal',exclusions:[],dislikes:'',medical:false,severeAllergy:false},dietPlan:null};
function clone(x){return structuredClone(x)}function mergeState(s){return{...clone(freshDefaults),...s,player:{...freshDefaults.player,...(s.player||{})},baseSkills:{...freshDefaults.baseSkills,...(s.baseSkills||{})},skillConfidence:{...freshDefaults.skillConfidence,...(s.skillConfidence||{})},days:s.days||{},academyProgress:s.academyProgress||{},monetization:{...freshDefaults.monetization,...(s.monetization||{})},dietProfile:{...freshDefaults.dietProfile,...(s.dietProfile||{})}}}
function load(){try{for(const key of[storeKey,v4Key,v3Key,v2Key,v1Key]){const raw=localStorage.getItem(key);if(!raw)continue;const old=JSON.parse(raw);if(key===storeKey)return mergeState(old);let s=mergeState(old);if(key===v1Key){s.player.name=old.playerName||'Jugador';if(old.baseAttributes){Object.entries(skillMap).forEach(([a,n])=>n.forEach(k=>s.baseSkills[k]=old.baseAttributes[a]??50))}}s.version=5;localStorage.setItem(storeKey,JSON.stringify(s));return s}}catch(e){console.warn(e)}return clone(freshDefaults)}let state=load();function persist(renderAfter=true){localStorage.setItem(storeKey,JSON.stringify(state));if(renderAfter)renderPage()}
function ensureAssessment(){if(page!=='assessment'&&!state.assessmentComplete)location.href='assessment.html'}
function contextLabel(){return({trabajo:'Trabajo',estudio:'Estudio',ambos:'Trabajo + estudio',independiente:'Independiente',busqueda:'Búsqueda laboral',otro:'Otro'})[state.player.context]||'Trabajo'}
function seedTasks(){const social=state.player.context==='estudio'?'Aclarar o coordinar algo con un compañero de estudio':'Aclarar o coordinar algo con un compañero';return[{id:crypto.randomUUID(),text:'Definir 3 prioridades del día',category:'Rendimiento',skill:'Organización',xp:2,done:false,custom:false},{id:crypto.randomUUID(),text:'Registrar o revisar un movimiento financiero',category:'Rendimiento',skill:'Finanzas personales',xp:2,done:false,custom:false},{id:crypto.randomUUID(),text:'Cumplir la actividad física planificada',category:'Físico',skill:'Salud física',xp:3,done:false,custom:false},{id:crypto.randomUUID(),text:'Resolver o avanzar un problema importante',category:'Intelecto',skill:'Resolución de problemas',xp:4,done:false,custom:false},{id:crypto.randomUUID(),text:social,category:'Carisma',skill:'Comunicación',xp:3,done:false,custom:false}]}
function inferSkill(t){if(t.skill&&allSkills.includes(t.skill))return t.skill;if(t.category==='Intelecto')return'Conocimiento';if(t.category==='Carisma')return'Comunicación';if(t.category==='Físico')return'Salud física';return'Disciplina'}
function getDay(){const k=todayKey();if(!state.days[k])state.days[k]={tasks:seedTasks(),checkin:{},events:[]};const d=state.days[k];d.tasks=(d.tasks||[]).map(t=>({...t,skill:inferSkill(t)}));d.checkin=d.checkin||{};d.events=d.events||[];return d}
function allDoneTasks(){const out=[];Object.entries(state.days).forEach(([date,d])=>(d.tasks||[]).forEach(t=>{if(t.done)out.push({...t,date,skill:inferSkill(t)})}));return out}function allEvents(){const out=[];Object.entries(state.days).forEach(([date,d])=>(d.events||[]).forEach(e=>out.push({...e,date})));return out}
function xpBySkill(){const totals=Object.fromEntries(allSkills.map(k=>[k,0]));allDoneTasks().forEach(t=>{if(totals[t.skill]!==undefined)totals[t.skill]+=+t.xp||0});allEvents().forEach(e=>{if(e.skill&&totals[e.skill]!==undefined)totals[e.skill]+=+e.xp||0});return totals}
function xpNeeded(s){if(s<40)return 8;if(s<60)return 10;if(s<75)return 14;if(s<90)return 20;return 30}function skillProgress(base,xp){let score=clamp(Math.round(+base||0)),remaining=Math.max(0,+xp||0),g=0;while(score<100&&remaining>=xpNeeded(score)&&g++<100){remaining-=xpNeeded(score);score++}return{score,currentXp:remaining,needed:score>=100?0:xpNeeded(score)}}
function measuredStrengthRows(){return(state.strength||[]).filter(x=>+x.max>0&&+x.current>0)}function rawForceScore(){const v=measuredStrengthRows();if(!v.length)return 0;return Math.round(v.map(x=>clamp(+x.current/+x.max*100)).reduce((a,b)=>a+b,0)/v.length)}
function behaviorCalibration(skill,base){const set=new Set(['Comunicación','Habilidades sociales','Liderazgo','Control emocional','Disciplina','Constancia','Organización','Productividad','Finanzas personales','Salud física']);if(!set.has(skill))return base;let total=0,done=0;Object.values(state.days).forEach(d=>(d.tasks||[]).forEach(t=>{if(inferSkill(t)===skill){total++;if(t.done)done++}}));if(total<8)return base;const observed=32+48*(done/total),w=Math.min(.30,.08+(total-8)*.005);return Math.round(base*(1-w)+observed*w)}
function baseSkillScore(skill){if(skill==='Fuerza'&&state.useMeasuredStrength&&measuredStrengthRows().length)return rawForceScore();return clamp(behaviorCalibration(skill,+state.baseSkills[skill]||50))}function effectiveConfidence(skill){if(skill==='Fuerza'&&state.useMeasuredStrength)return measuredStrengthRows().length>=4?'alta':'media';let base=state.skillConfidence[skill]||'baja',total=0,done=0;Object.values(state.days).forEach(d=>(d.tasks||[]).forEach(t=>{if(inferSkill(t)===skill){total++;if(t.done)done++}}));const ac=Object.entries(state.academyProgress).filter(([id,p])=>p.completed&&academyLessons.find(l=>l.id===id)?.skill===skill).length;if(total>=25&&done>=12)return'alta';if((total>=10&&done>=5)||ac>=3)return base==='alta'?'alta':'media';return base}
function effectiveSkillData(){const xp=xpBySkill(),out={};allSkills.forEach(skill=>out[skill]={...skillProgress(baseSkillScore(skill),xp[skill]),totalXp:xp[skill],base:baseSkillScore(skill),confidence:effectiveConfidence(skill)});return out}function effectiveAttributes(){const s=effectiveSkillData(),out={};Object.entries(skillMap).forEach(([a,n])=>out[a]=Math.round(n.reduce((x,k)=>x+s[k].score,0)/n.length));return out}function generalLevel(){const a=Object.values(effectiveAttributes());return Math.round(a.reduce((x,y)=>x+y,0)/a.length)}function dayXp(d){return(d.tasks||[]).filter(t=>t.done).reduce((s,t)=>s+(+t.xp||0),0)+(d.events||[]).reduce((s,e)=>s+(+e.xp||0),0)}
function completedDayKeys(){return Object.keys(state.days).filter(k=>(state.days[k].tasks||[]).some(t=>t.done)||(state.days[k].events||[]).length).sort()}function streaks(){const keys=completedDayKeys();if(!keys.length)return{current:0,best:state.bestStreak||0};let best=0,run=0,prev=null;keys.forEach(k=>{const d=new Date(k+'T12:00:00');if(prev&&(d-prev)/86400000===1)run++;else run=1;best=Math.max(best,run);prev=d});const set=new Set(keys);let cur=0,d=new Date();for(;;){const k=dateKey(d);if(set.has(k)){cur++;d.setDate(d.getDate()-1)}else break}state.bestStreak=Math.max(state.bestStreak||0,best);return{current:cur,best:state.bestStreak}}
function renderAttributes(sel='#attributesGrid'){const el=$(sel);if(!el)return;const attrs=effectiveAttributes(),xp=xpBySkill(),data=effectiveSkillData();el.innerHTML=Object.entries(attrs).map(([a,v])=>{const total=skillMap[a].reduce((s,n)=>s+xp[n],0),conf=skillMap[a].reduce((s,n)=>s+(data[n].confidence==='alta'?3:data[n].confidence==='media'?2:1),0)/5,label=conf>=2.5?'alta':conf>=1.65?'media':'baja';return`<div class="attribute-card"><div class="small">${icons[a]} ${a}</div><div class="score">${v}</div><div class="progress"><span style="width:${v}%"></span></div><div class="small">${rank(v)} · ${total} XP</div><div class="confidence">confianza ${label}</div></div>`}).join('')}
function renderAchievements(){const el=$('#achievements');if(!el)return;const actions=allDoneTasks().length+allEvents().length,st=streaks(),gl=generalLevel(),xp=Object.values(xpBySkill()).reduce((a,b)=>a+b,0),lessons=Object.values(state.academyProgress).filter(x=>x.completed).length;const list=[['Primer paso','Completar 1 acción',actions>=1],['En marcha','Completar 10 acciones',actions>=10],['Racha x7','Actividad 7 días seguidos',st.best>=7],['100 XP','Acumular 100 XP',xp>=100],['Estudiante','Completar 5 lecciones',lessons>=5],['Academia completa','Completar 15 lecciones',lessons>=15],['Nivel 70','Llegar a nivel general 70',gl>=70]];el.innerHTML=list.map(x=>`<div class="achievement ${x[2]?'':'locked'}"><strong>${x[2]?'🏆':'🔒'} ${x[0]}</strong><span class="note">${x[1]}</span></div>`).join('')}
function renderHome(){if($('#upgradeBanner'))$('#upgradeBanner').classList.toggle('hidden',!(state.assessmentComplete&&state.assessmentEngineVersion<5));$('#homeName').textContent=state.player.name||'Jugador';const gl=generalLevel();$('#generalLevel').textContent=gl;$('#generalBar').style.width=gl+'%';$('#rankPill').textContent=rank(gl);$('#homeMeta').textContent=[state.player.age?`${state.player.age} años`:null,state.player.height?`${state.player.height} cm`:null,state.player.weight?`${state.player.weight} kg`:null,contextLabel()].filter(Boolean).join(' · ');if(state.avatar)$('#avatar').src=state.avatar;renderAttributes();const d=getDay();$('#todayXp').textContent=dayXp(d);$('#todayTasks').textContent=`${d.tasks.filter(t=>t.done).length}/${d.tasks.length}`;$('#homeStreak').textContent=streaks().current;$('#homeLessons').textContent=`${academyCompletedToday()}/2`;renderAchievements()}
function updateSkillSelect(){const a=$('#newTaskCategory');if(!a)return;const s=$('#newTaskSkill'),cur=s.value;s.innerHTML=skillMap[a.value].map(x=>`<option>${escapeHtml(x)}</option>`).join('');if(skillMap[a.value].includes(cur))s.value=cur}
function renderTasks(){const d=getDay();$('#dailyTasks').innerHTML=d.tasks.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-id="${t.id}" ${t.done?'checked':''}><div><div class="task-title">${escapeHtml(t.text)}</div><div class="task-meta">${escapeHtml(t.skill)}</div></div><span class="tag">${t.category}</span><span class="task-xp">+${t.xp} XP</span>${t.custom?`<button class="delete-task" data-del="${t.id}">×</button>`:''}</div>`).join('');$('#todayXp').textContent=dayXp(d);$('#sleepHours').value=d.checkin.sleepHours??'';$('#energy').value=d.checkin.energy??'';$('#mood').value=d.checkin.mood??'';$('#dayNote').value=d.checkin.note??'';$('#reminderTime').value=state.reminderTime||'21:00';$('#reminderText').value=state.reminderText||freshDefaults.reminderText;updateSkillSelect()}
function renderSkills(){renderAttributes();const data=effectiveSkillData();$('#skillsGrid').innerHTML=Object.entries(skillMap).map(([a,n])=>`<section class="skill-group"><h3>${icons[a]} ${a}</h3>${n.map(k=>{const d=data[k],pct=d.needed?clamp(d.currentXp/d.needed*100):100;return`<div class="skill-row"><div class="skill-top"><span>${escapeHtml(k)}</span><strong>${d.score}</strong></div><div class="skill-xp">${d.score>=100?'Nivel máximo':`${d.currentXp}/${d.needed} XP para subir · ${d.totalXp} histórico`}</div><div class="progress"><span style="width:${pct}%"></span></div><div class="confidence">estimación ${d.confidence}</div></div>`}).join('')}</section>`).join('')}
let academyFilter='all',currentLesson=null;function academyCompletedToday(){return Object.values(state.academyProgress).filter(p=>p.completed&&p.completedAt&&dateKeyFromIso(p.completedAt)===todayKey()).length}function academyAllowance(){if(state.monetization.premium)return Infinity;return 2+(state.monetization.bonusLessons[todayKey()]||0)}function canCompleteLesson(){return academyCompletedToday()<academyAllowance()}
function renderAcademy(){const progress=state.academyProgress;$('#academyCompleted').textContent=Object.values(progress).filter(x=>x.completed).length;const today=academyCompletedToday(),allow=academyAllowance();$('#academyDailyText').textContent=state.monetization.premium?'Premium · lecciones ilimitadas':`${today}/${allow===Infinity?'∞':allow} lecciones disponibles usadas hoy`;$('#academyAccessPill').textContent=state.monetization.premium?'PREMIUM':'GRATIS';const list=academyFilter==='all'?academyLessons:academyLessons.filter(l=>l.category===academyFilter);$('#academyGrid').innerHTML=list.map(l=>{const done=progress[l.id]?.completed,locked=!done&&!canCompleteLesson();return`<article class="lesson-card ${done?'completed':''} ${locked?'locked':''}" data-lesson="${l.id}"><div class="lesson-icon">${l.icon}</div><div class="eyebrow">${l.category}</div><h3>${escapeHtml(l.title)}</h3><p>${escapeHtml(l.summary)}</p><footer><span>${l.minutes} min · +${l.xp} XP</span><strong class="${locked?'lock-note':''}">${done?'✓ completada':locked?'🔒 límite diario':'Abrir →'}</strong></footer></article>`}).join('')}
function openLesson(id){const l=academyLessons.find(x=>x.id===id);if(!l)return;if(!state.academyProgress[id]?.completed&&!canCompleteLesson())return openPaywall();currentLesson=l;$('#lessonOverlay').classList.remove('hidden');$('#lessonCategory').textContent=l.category;$('#lessonTitle').textContent=l.title;$('#lessonBody').innerHTML=l.body.map(p=>`<p>${escapeHtml(p)}</p>`).join('');$('#lessonQuestion').textContent=l.question;$('#lessonAnswers').innerHTML=l.answers.map((a,i)=>`<button class="answer-btn" data-lesson-answer="${i}">${escapeHtml(a)}</button>`).join('');$('#lessonFeedback').className='quiz-feedback';$('#lessonFeedback').textContent=''}function closeLesson(){$('#lessonOverlay').classList.add('hidden');currentLesson=null}function openPaywall(){$('#paywallOverlay').classList.remove('hidden');$('#monetizationMessage').textContent='';$('#monetizationMessage').className='quiz-feedback'}function closePaywall(){$('#paywallOverlay').classList.add('hidden')}
function answerLesson(i){if(!currentLesson)return;const fb=$('#lessonFeedback');if(i!==currentLesson.correct){fb.className='quiz-feedback bad';fb.textContent='No es esa. Volvé al texto y elegí la opción que mejor representa la idea de la lección.';return}if(state.academyProgress[currentLesson.id]?.completed){fb.className='quiz-feedback good';fb.textContent='Correcto. Ya habías completado esta lección, así que no suma XP otra vez.';return}if(!canCompleteLesson()){closeLesson();openPaywall();return}state.academyProgress[currentLesson.id]={completed:true,completedAt:new Date().toISOString(),xp:currentLesson.xp};getDay().events.push({id:`academy:${currentLesson.id}`,type:'academy',text:`Lección: ${currentLesson.title}`,skill:currentLesson.skill,xp:currentLesson.xp});persist(false);fb.className='quiz-feedback good';fb.textContent=`Correcto. +${currentLesson.xp} XP en ${currentLesson.skill}.`;renderAcademy()}
function renderProfile(){const gl=generalLevel();$('#playerName').value=state.player.name||'Jugador';$('#generalLevel').textContent=gl;$('#generalBar').style.width=gl+'%';$('#rankPill').textContent=rank(gl);$('#profileMeta').textContent=[state.player.age?`${state.player.age} años`:null,state.player.height?`${state.player.height} cm`:null,state.player.weight?`${state.player.weight} kg`:null,contextLabel()].filter(Boolean).join(' · ');$('#assessmentMeta').textContent=state.assessmentComplete?`Evaluación V${state.assessmentEngineVersion||4} · confianza global ${globalConfidence()} · Nutrición ${state.nutritionKnowledge||0}%`:'Evaluación pendiente';if(state.avatar)$('#avatar').src=state.avatar;$('#profileAge').value=state.player.age??'';$('#profileHeight').value=state.player.height??'';$('#profileWeight').value=state.player.weight??'';$('#profileContext').value=state.player.context||'trabajo';renderStrength()}
function globalConfidence(){const v=Object.values(state.skillConfidence),s=v.reduce((a,x)=>a+(x==='alta'?3:x==='media'?2:1),0)/(v.length||1);return s>=2.5?'alta':s>=1.65?'media':'baja'}function renderStrength(){const scores=state.strength.map(x=>+x.max>0?clamp(+x.current/+x.max*100):0);$('#forceScore').textContent=baseSkillScore('Fuerza');$('#strengthModeNote').textContent=state.useMeasuredStrength&&measuredStrengthRows().length?'La Fuerza usa los ejercicios con peso actual cargado.':'Todavía se usa una estimación de baja confianza. Cargar métricas reales mejora la calibración.';$('#strengthTable').innerHTML=state.strength.map((x,i)=>`<tr><td><input class="exercise-name" data-strength-name="${i}" value="${escapeHtml(x.name)}"></td><td><input type="number" step="2.5" min="0" data-strength="${i}" value="${x.current}"> kg</td><td><input type="number" step="2.5" min="1" data-strength-max="${i}" value="${x.max}"> kg</td><td>${Math.round(scores[i])}</td></tr>`).join('')}
function datesWithin(days){const cut=new Date();cut.setHours(0,0,0,0);cut.setDate(cut.getDate()-(days-1));return Object.entries(state.days).filter(([k])=>new Date(k+'T12:00:00')>=cut)}function summaryFor(days){const e=datesWithin(days);return{xp:e.reduce((s,[,d])=>s+dayXp(d),0),actions:e.reduce((s,[,d])=>s+(d.tasks||[]).filter(t=>t.done).length+(d.events||[]).length,0)}}function formatDate(k){return new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date(k+'T12:00:00'))}
function renderHistory(){const w=summaryFor(7),m=summaryFor(30),st=streaks();$('#weekXp').textContent=`${w.xp} XP`;$('#weekTasks').textContent=`${w.actions} acciones`;$('#monthXp').textContent=`${m.xp} XP`;$('#monthTasks').textContent=`${m.actions} acciones`;$('#streak').textContent=`${st.current} días`;$('#bestStreak').textContent=`${st.best} días`;$('#actionsCompleted').textContent=`${allDoneTasks().length+allEvents().length} acciones`;const entries=Object.entries(state.days).sort(([a],[b])=>b.localeCompare(a));$('#historyList').innerHTML=entries.length?entries.map(([date,d])=>{const done=(d.tasks||[]).filter(t=>t.done),ev=d.events||[],c=d.checkin||{},items=[...done.map(t=>`<div class="history-task"><span>✓ ${escapeHtml(t.text)} <small>· ${escapeHtml(t.skill)}</small></span><strong>+${t.xp}</strong></div>`),...ev.map(e=>`<div class="history-task academy-event"><span>📚 ${escapeHtml(e.text)} <small>· ${escapeHtml(e.skill||'Aprendizaje')}</small></span><strong>+${e.xp||0}</strong></div>`)],check=[c.sleepHours?`Sueño ${c.sleepHours}h`:null,c.energy?`Energía ${c.energy}/10`:null,c.mood?`Ánimo ${c.mood}/10`:null].filter(Boolean).join(' · ');return`<article class="history-day"><div class="history-head"><div><strong>${formatDate(date)}</strong><br><small>${done.length+ev.length} acciones</small></div><span class="xp-badge">${dayXp(d)} XP</span></div><div class="history-body">${items.length?`<div class="history-tasks">${items.join('')}</div>`:'<div class="empty">Sin acciones completadas.</div>'}${check||c.note?`<div class="history-checkin">${check}${c.note?`${check?' · ':''}${escapeHtml(c.note)}`:''}</div>`:''}</div></article>`}).join(''):'<div class="empty">Todavía no hay historial.</div>'}
