function dietCandidates(type,p){const dislikes=(p.dislikes||'').toLowerCase().split(/[,;\n]+/).map(x=>x.trim()).filter(x=>x.length>=3);return mealDB.filter(m=>m.type===type&&m.styles.includes(p.style)&&!m.allergens.some(a=>p.exclusions.includes(a))&&(p.budget!=='low'||m.budget==='low')&&!dislikes.some(x=>(m.name+' '+m.desc).toLowerCase().includes(x)))}function pick(arr,n){if(!arr.length)return null;return arr[n%arr.length]}
function nutritionTargets(p){const age=+state.player.age,w=+state.player.weight,h=+state.player.height;if(!age||!w||!h)return{error:'Completá edad, altura y peso en Perfil antes de generar el dietario.'};if(age<18)return{error:'El plan automático está disponible sólo para adultos de 18 años o más.'};if(p.medical)return{error:'Marcaste una situación que requiere planificación profesional. La app no va a generar automáticamente un plan para este caso.'};if(p.severeAllergy)return{error:'Con una alergia alimentaria grave, un generador automático no puede garantizar seguridad ni contaminación cruzada. Usá un plan profesional.'};let constant=p.sex==='male'?5:p.sex==='female'?-161:-78;const bmr=10*w+6.25*h-5*age+constant,tdee=bmr*(+p.activity||1.5),factor=p.goal==='lose'?.88:p.goal==='gain'?1.08:1;const calories=Math.round(tdee*factor/10)*10,proteinFactor=p.goal==='lose'?1.8:p.goal==='gain'?1.7:(+p.activity>=1.5?1.6:1.4),protein=Math.round(w*proteinFactor),fat=Math.max(45,Math.round(w*.8));let carbs=Math.round((calories-protein*4-fat*9)/4);if(carbs<100){const adjustedFat=Math.max(40,Math.round((calories-protein*4-400)/9));carbs=Math.round((calories-protein*4-adjustedFat*9)/4);return{bmr:Math.round(bmr),tdee:Math.round(tdee),calories,protein,fat:adjustedFat,carbs,fiber:Math.round(clamp(calories/1000*14,25,38))}}return{bmr:Math.round(bmr),tdee:Math.round(tdee),calories,protein,fat,carbs,fiber:Math.round(clamp(calories/1000*14,25,38))}}
function generateDiet(p){const t=nutritionTargets(p);if(t.error)return t;const days=[];for(let d=0;d<7;d++){let types=p.meals===3?['breakfast','lunch','dinner']:p.meals===5?['breakfast','snack','lunch','snack','dinner']:['breakfast','lunch','snack','dinner'];let meals=types.map((type,i)=>pick(dietCandidates(type,p),d+i*2)).filter(Boolean);if(meals.length!==types.length)return{error:'Con esas exclusiones no quedan suficientes comidas en la base actual. Probá quitar alguna exclusión o cambiar el estilo.'};const base=meals.reduce((s,m)=>s+m.kcal,0),scale=clamp(t.calories/base,.65,1.55);const scaled=meals.map(m=>({...m,scale,kcal:Math.round(m.kcal*scale),p:Math.round(m.p*scale),c:Math.round(m.c*scale),f:Math.round(m.f*scale),fiber:Math.round(m.fiber*scale)}));days.push({day:d+1,meals:scaled,totals:{kcal:scaled.reduce((s,m)=>s+m.kcal,0),p:scaled.reduce((s,m)=>s+m.p,0),c:scaled.reduce((s,m)=>s+m.c,0),f:scaled.reduce((s,m)=>s+m.f,0),fiber:scaled.reduce((s,m)=>s+m.fiber,0)}})}return{createdAt:new Date().toISOString(),profile:p,targets:t,days}}
function renderDietProfile(){const p=state.player;$('#dietProfileMeta').textContent=[p.age?`${p.age} años`:null,p.height?`${p.height} cm`:null,p.weight?`${p.weight} kg`:null,contextLabel()].filter(Boolean).join(' · ')||'Faltan datos de perfil';const dp=state.dietProfile;$('#dietGoal').value=dp.goal;$('#dietSex').value=dp.sex;$('#dietActivity').value=dp.activity;$('#dietMeals').value=dp.meals;$('#dietStyle').value=dp.style;$('#dietBudget').value=dp.budget;$('#dietDislikes').value=dp.dislikes||'';$('#dietMedical').checked=!!dp.medical;$('#dietSevereAllergy').checked=!!dp.severeAllergy;$$('[name=dietExclude]').forEach(x=>x.checked=(dp.exclusions||[]).includes(x.value));if(state.dietPlan)renderDietResults(state.dietPlan)}
function renderDietResults(plan){const box=$('#dietResults');box.classList.remove('hidden');if(plan.error){$('#macroGrid').innerHTML='';$('#dietEstimateNote').innerHTML=`<span style="color:#fecdd3">${escapeHtml(plan.error)}</span>`;$('#dietDays').innerHTML='';return}const t=plan.targets,goal=plan.profile.goal==='lose'?'déficit calórico moderado':plan.profile.goal==='gain'?'superávit calórico moderado':'mantenimiento estimado';$('#macroGrid').innerHTML=[['Calorías',`${t.calories} kcal`],['Proteína',`${t.protein} g`],['Carbos',`${t.carbs} g`],['Grasas',`${t.fat} g`],['Fibra',`≈${t.fiber} g`]].map(x=>`<div class="macro-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');$('#dietEstimateNote').textContent=`Gasto de mantenimiento estimado: ${t.tdee} kcal/día · objetivo: ${goal}. Los valores de las comidas son aproximados; marcas, cocción y porciones reales cambian los números.`;$('#dietDays').innerHTML=plan.days.map((d,i)=>`<details class="diet-day" ${i===0?'open':''}><summary><span>Día ${d.day}</span><span>${d.totals.kcal} kcal · ${d.totals.p} g proteína</span></summary><div class="meal-list">${d.meals.map((m,j)=>`<article class="meal"><div class="meal-top"><div><h4>${({breakfast:'Desayuno',lunch:'Almuerzo',snack:'Colación',dinner:'Cena'})[m.type]||'Comida'} · ${escapeHtml(m.name)}</h4><p>${escapeHtml(m.desc)} · porción aproximada ×${m.scale.toFixed(2)}</p></div><span class="pill cyan">${m.kcal} kcal</span></div><div class="meal-macros">P ${m.p} g · C ${m.c} g · G ${m.f} g · fibra ~${m.fiber} g</div></article>`).join('')}</div></details>`).join('')}
