function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}const choice=(label,value)=>({label,value}),objectiveChoice=(label,correct)=>({label,correct});const prepareQuestion=q=>({...q,options:shuffle(q.options.map(o=>({...o})))});
